def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    divider_rows = [
        r for r in range(h)
        if len(set(grid[r])) == 1 and grid[r][0] != background
    ]
    divider_cols = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
        and grid[0][c] != background
    ]

    def sections(length, dividers):
        result = []
        start = 0
        for d in dividers:
            if start < d:
                result.append((start, d))
            start = d + 1
        if start < length:
            result.append((start, length))
        return result

    row_sections = sections(h, divider_rows)
    col_sections = sections(w, divider_cols)
    blocks = [
        (r0, r1, c0, c1)
        for r0, r1 in row_sections
        for c0, c1 in col_sections
    ]

    source = max(
        blocks,
        key=lambda b: sum(
            grid[r][c] != background
            for r in range(b[0], b[1])
            for c in range(b[2], b[3])
        )
    )
    r0, r1, c0, c1 = source
    motif = [row[c0:c1] for row in grid[r0:r1]]
    mh, mw = len(motif), len(motif[0])

    out = [row[:] for row in grid]
    for a, b, x, y in blocks:
        for r in range(a, b):
            for c in range(x, y):
                out[r][c] = motif[(r - a) % mh][(c - x) % mw]
    return out
